from pathlib import Path
import html,json,re
import markdown
ROOT=Path(__file__).resolve().parents[1]
md=lambda s:markdown.markdown(s,extensions=['tables','fenced_code','sane_lists'])
assignments=json.loads((ROOT/'assessments/assignments.json').read_text())
assessments=json.loads((ROOT/'assessments/module-assessments.json').read_text())
lessons=sorted((ROOT/'lessons').glob('*.md'))
nav=[];pages=[];search={}
for i,path in enumerate(lessons,1):
 raw=path.read_text();title=raw.splitlines()[0][2:];id=f'lesson-{i:02}';a=assignments[i-1]
 nav.append(f'<button class="lesson-link" data-page="{id}"><span class="num">{i:02}</span><span>{html.escape(title.split(": ",1)[-1])}</span><span class="tick" aria-hidden="true"></span></button>')
 content=md(raw)
 pages.append(f'''<article class="page lesson" id="{id}" data-lesson="{i}" hidden><div class="eyebrow">Module {(i+1)//2} · Lesson {i} of 24</div>{content}<section class="assignment"><div class="eyebrow">Your assignment</div><h2>{html.escape(a['title'])}</h2>{md(a['prompt'])}<p class="command">python labs/run_lab.py {a['lab']}</p><details class="solution"><summary>Reveal the worked solution</summary>{md(a['solution'])}</details></section><section class="notes"><label for="note-{i}">Your prediction, evidence, and remaining question</label><textarea id="note-{i}" data-note="{i}" rows="4" placeholder="Saved locally when your browser permits storage. Export progress to keep a portable copy."></textarea><label class="completion"><input type="checkbox" data-complete="{i}"> Mark this lesson studied</label></section><div class="lesson-actions">{f'<button data-page="lesson-{i-1:02}">← Previous lesson</button>' if i>1 else '<button data-page="home">Course home</button>'}{f'<button class="primary" data-page="lesson-{i+1:02}">Next lesson →</button>' if i<24 else '<button class="primary" data-page="assessments">Final assessments →</button>'}</div></article>''')
 search[id]=(title+' '+raw+' '+a['prompt']).lower()
home='''<div class="eyebrow">Complete edition · Research snapshot 12 September 2026</div><h1>Engineer the system<br>around the model.</h1><p class="lead">An advanced course in harness engineering, multi-agent orchestration, LangGraph, evaluation, and reliable operation.</p><div class="stats"><div><strong>24</strong><span>Written lessons</span></div><div><strong>12</strong><span>Executable labs</span></div><div><strong>12</strong><span>Interactive models</span></div><div><strong>2</strong><span>Reference capstones</span></div></div><div class="callout"><h2>Every lesson is ready.</h2><p>Read, predict, build, inject a failure, and defend the result. Each lesson includes an assignment and a revealable worked answer. Study at your pace; the complete course does not depend on future material being authored.</p><button class="primary" data-page="lesson-01">Begin Lesson 1 →</button><button data-page="visuals">Explore the visual models</button></div><h2>The path to mastery</h2><div class="phases"><div><b>01 / Foundations</b><p>Control loops, context, tools, evaluation, and statistics.</p></div><div><b>02 / Runtime</b><p>LangGraph, reducers, durable effects, approval, and recovery.</p></div><div><b>03 / Coordination</b><p>Topologies, worker contracts, protocols, long work, and memory.</p></div><div><b>04 / Expert practice</b><p>Security, operations, optimization, adaptive compute, and engineering defense.</p></div></div><h2>How to use this reader</h2><p>Use the left navigation to open any lesson. Search matches lesson content as well as titles. Notes and completion checks stay in your browser when storage is available; export progress for a portable backup. The ZIP contains runnable code, notebooks, PDFs, templates, source text, and recorded verification evidence.</p><p>The suggested pace is 24 weeks at 15–20 hours per week, including implementation and experiments. Reading alone is not the mastery criterion. All default labs are local reference mechanics; live-model performance remains a separate experiment.</p>'''
pages.insert(0,'<article class="page" id="home">'+home+'</article>')
for id,title,file in [('guide','Start here','START-HERE.md'),('research','Research foundation','RESEARCH.md'),('curriculum','Curriculum','CURRICULUM.md'),('labs','Lab guide','labs/README.md'),('reference','Quick reference','QUICK-REFERENCE.md')]:
 pages.append(f'<article class="page" id="{id}" hidden>'+md((ROOT/file).read_text())+'</article>')
assessment_html='<div class="eyebrow">Twelve module checkpoints</div><h1>Defend the boundary.</h1><p>Answer before revealing the key. Each assessment awards 4 points for diagnosis, 3 for an enforceable repair, 2 for a discriminating test, and 1 for limitations. Target at least 8/10; correct any unsafe authority or false-outcome claim regardless of the score.</p>'
for a in assessments:assessment_html+=f'<section class="assignment"><h2>Module {a["module"]}: {html.escape(a["title"])}</h2>{md(a["prompt"])}<details><summary>Reveal the assessment key</summary>{md(a["answer"])}</details></section>'
assessment_html+=md((ROOT/'assessments/WORKBOOK.md').read_text().split('## Capstone A brief:',1)[1].join(['## Capstone A brief:','']))
assessment_html+=md((ROOT/'assessments/TRACE-CASES.md').read_text())+'<details><summary>Reveal additional trace and design keys</summary>'+md((ROOT/'solutions/TRACE-KEY.md').read_text())+'</details>'
pages.append('<article class="page" id="assessments" hidden>'+assessment_html+'</article>')
pages.append('''<article class="page wide" id="visuals" hidden><div class="eyebrow">Twelve interactive models · Fully offline</div><h1>Make a prediction.<br>Then change one variable.</h1><p>These models expose control, context, scheduling, reliability, state, and authority. Their numbers are illustrative, with assumptions displayed in each model.</p><div class="atlas-controls"><button class="primary" id="show-foundations">Models 1–5: Foundations</button><button id="show-advanced">Models 6–12: Advanced</button></div><iframe id="foundation-frame" title="Five foundational harness experiments" sandbox="allow-scripts allow-same-origin"></iframe><iframe id="advanced-frame" title="Seven advanced harness experiments" sandbox="allow-scripts allow-same-origin" hidden></iframe><p class="small">The same atlases are included as separate HTML files in the ZIP. Interactive controls are available here; printable books contain the explanations and worked calculations.</p></article>''')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f5ef;color:#1b3030;font:16px/1.7 system-ui,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer;border:1px solid #ccd7cf;background:white;color:#1b3030;border-radius:6px;padding:10px 15px}button:hover{background:#e8efe8}button.primary{background:#20675b;color:white;border-color:#20675b}button:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #d5a645;outline-offset:3px}a{color:#216b61;text-underline-offset:3px;overflow-wrap:anywhere}header{position:sticky;top:0;z-index:20;background:#f7f5eff5;border-bottom:1px solid #d5ded5;padding:13px 24px;display:flex;align-items:center;justify-content:space-between;gap:14px;backdrop-filter:blur(8px)}.brand{font-weight:750;letter-spacing:.5px;font-size:14px}.brand span{font-weight:400;color:#657571}.header-tools{display:flex;align-items:center;gap:8px}.header-tools button{font-size:12px;padding:7px 10px}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);max-width:1580px;margin:auto}aside{position:sticky;top:62px;height:calc(100vh - 62px);overflow:auto;border-right:1px solid #d5ded5;padding:24px 14px 40px}aside input{width:100%;padding:10px;border:1px solid #bdcbc1;border-radius:6px;margin-bottom:15px;background:#fff}.nav-label{font-size:11px;font-weight:750;letter-spacing:1.4px;color:#63756e;text-transform:uppercase;padding:18px 10px 7px}.resource-nav{display:grid;grid-template-columns:1fr 1fr;gap:5px}.resource-nav button{font-size:12px;padding:7px 4px}.lesson-link{display:grid;grid-template-columns:23px 1fr 15px;gap:9px;text-align:left;border:0;background:transparent;width:100%;padding:10px 8px;font-size:13px;line-height:1.4;margin:3px 0}.lesson-link.active{background:#dfece3;font-weight:650}.num{color:#718279;font:12px/1.5 ui-monospace,monospace}.tick{color:#216b61}main{min-width:0;padding:45px clamp(22px,5vw,85px) 80px}.page{max-width:850px;margin:auto}.page.wide{max-width:1100px}.page[hidden],[hidden]{display:none!important}.eyebrow{font-size:11px;letter-spacing:1.8px;text-transform:uppercase;color:#267263;font-weight:750}h1{font:600 clamp(32px,4vw,53px)/1.14 Georgia,serif;letter-spacing:-.7px;margin:18px 0 26px}h2{font:600 27px/1.25 Georgia,serif;margin:36px 0 15px;scroll-margin-top:85px}h3{font-size:19px;margin:27px 0 10px}p,li{max-width:78ch}.lead{font-size:20px;color:#4f6660;line-height:1.5}.stats{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #cfdbd1;border-bottom:1px solid #cfdbd1;margin:30px 0;padding:23px 0;gap:16px}.stats strong{display:block;font:600 37px Georgia,serif}.stats span{font-size:12px;color:#597068}.callout{padding:28px;background:#e5eee5;border-radius:10px;margin:28px 0}.callout h2{margin-top:0}.callout button{margin:6px 6px 0 0}.phases{display:grid;grid-template-columns:1fr 1fr;gap:16px}.phases>div{border-top:2px solid #96ae9c;padding-top:18px}.phases b{font-size:13px}.phases p{margin:8px 0;color:#4f6660;font-size:14px}pre{background:#e9eee7;padding:18px;overflow:auto;border-radius:6px;font-size:13px;line-height:1.6}code{font-family:ui-monospace,monospace;font-size:.86em;overflow-wrap:anywhere}pre code{font-size:inherit;overflow-wrap:normal}table{border-collapse:collapse;width:100%;font-size:13px;display:block;overflow:auto}th,td{border-bottom:1px solid #cbd7cd;padding:10px 12px;text-align:left;vertical-align:top;min-width:130px}th{background:#e5ece4}blockquote{border-left:3px solid #7a9b86;padding-left:18px;color:#53685e}.assignment{border:1px solid #cbd9cc;background:#fff;border-radius:9px;padding:25px;margin:36px 0}.assignment h2{margin-top:10px}.command{font:13px/1.6 ui-monospace,monospace;background:#edf2eb;padding:12px}details{border-top:1px solid #d4ded3;padding-top:14px;margin-top:20px}summary{cursor:pointer;font-weight:650;color:#216b61}details p{font-size:15px}.notes{margin:30px 0}.notes label{font-size:13px;font-weight:600;display:block}.notes textarea{width:100%;padding:12px;border:1px solid #bdcec0;border-radius:7px;resize:vertical;background:#fff;margin:8px 0 12px;line-height:1.5;font-size:14px}.completion input{accent-color:#20675b}.lesson-actions{display:flex;justify-content:space-between;gap:15px;margin-top:35px}.small{font-size:12px;color:#5d7168}.atlas-controls{display:flex;flex-wrap:wrap;gap:10px;margin:25px 0}iframe{width:100%;height:1450px;border:1px solid #cbd8ca;border-radius:10px;background:#f7f5ef}.progressbar{height:5px;background:#dce5db;border-radius:5px;overflow:hidden;min-width:90px}.progressbar span{display:block;height:100%;background:#20675b}.progress-count{font-size:12px;color:#526b5e}#storage-status{font-size:11px;color:#786039;padding:0 8px}#menu-button{display:none}#search-empty{font-size:13px;padding:10px;color:#6a7569}noscript{display:block;background:#fff0d5;padding:20px}@media(max-width:1000px){.layout{grid-template-columns:255px minmax(0,1fr)}main{padding:32px 25px}.brand span{display:none}.stats{grid-template-columns:1fr 1fr}}@media(max-width:720px){#menu-button{display:inline-block}.layout{display:block}aside{display:none;position:fixed;z-index:30;top:64px;left:0;width:min(340px,92vw);height:calc(100vh - 64px);background:#f7f5ef;box-shadow:10px 0 40px #182b2926}body.nav-open aside{display:block}header{padding:10px 12px;min-height:64px}.brand{font-size:12px}.header-tools{gap:5px}.header-tools button{font-size:11px;padding:6px}#progress-export{display:none}.progressbar{min-width:45px}.progress-count{font-size:11px}main{padding:30px 18px 60px}.phases{grid-template-columns:1fr}.assignment{padding:18px}.lesson-actions button{font-size:13px}.stats{gap:12px}iframe{height:1800px}.header-tools .import-label{display:none}}@media print{header,aside,.notes,.lesson-actions,.atlas-controls{display:none!important}.layout{display:block}main{padding:0}.page:not([hidden]){display:block}body{background:white}details{display:block}iframe{display:none}h1{font-size:28px}a{color:inherit}}'''
js=''''use strict';const $=id=>document.getElementById(id);const key='harness-course-complete-v1';let progress={version:1,completed:[],notes:{}},storageOK=true;try{const p=JSON.parse(localStorage.getItem(key)||'null');if(p&&p.version===1&&Array.isArray(p.completed)&&p.notes&&typeof p.notes==='object')progress=p}catch(e){storageOK=false}const SEARCH=__SEARCH__;const ATLASES=__ATLASES__;let atlasesLoaded=false;
function save(){try{localStorage.setItem(key,JSON.stringify(progress))}catch(e){storageOK=false}if(!storageOK)$('storage-status').textContent='Browser storage unavailable. Export progress before closing.';updateProgress()}
function updateProgress(){const count=progress.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=24).length;$('progress-count').textContent=count+'/24';$('progress-fill').style.width=(count/24*100)+'%';document.querySelectorAll('[data-complete]').forEach(x=>x.checked=progress.completed.includes(+x.dataset.complete));document.querySelectorAll('.lesson-link').forEach(x=>{const n=+x.dataset.page.split('-')[1];x.querySelector('.tick').textContent=progress.completed.includes(n)?'✓':''})}
function show(id){if(!$(id)||!$(id).classList.contains('page'))id='home';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));document.body.classList.remove('nav-open');$('menu-button').setAttribute('aria-expanded','false');if(id==='visuals'&&!atlasesLoaded){$('foundation-frame').srcdoc=ATLASES.foundation;$('advanced-frame').srcdoc=ATLASES.advanced;atlasesLoaded=true}history.replaceState(null,'','#'+id);window.scrollTo({top:0,left:0,behavior:"instant"});document.title=(id.startsWith('lesson-')?$(id).querySelector('h1').textContent:'Harness Engineering — Complete Course')}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.page)));document.querySelectorAll('[data-note]').forEach(t=>{t.value=typeof progress.notes[t.dataset.note]==='string'?progress.notes[t.dataset.note]:'';t.addEventListener('input',()=>{progress.notes[t.dataset.note]=t.value;save()})});document.querySelectorAll('[data-complete]').forEach(c=>c.addEventListener('change',()=>{const n=+c.dataset.complete;progress.completed=progress.completed.filter(x=>x!==n);if(c.checked)progress.completed.push(n);save()}));
$('search').addEventListener('input',()=>{const q=$('search').value.toLowerCase().trim();let count=0;document.querySelectorAll('.lesson-link').forEach(b=>{const match=!q||SEARCH[b.dataset.page].includes(q);b.hidden=!match;if(match)count++});$('search-empty').hidden=count>0});
function exportProgress(){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='harness-course-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('progress-export').onclick=exportProgress;$('sidebar-export').onclick=exportProgress;$('progress-import-button').onclick=()=>$('progress-import').click();$('progress-import').onchange=async()=>{try{const file=$('progress-import').files[0];if(!file)return;if(file.size>1000000)throw Error('Progress file too large');const p=JSON.parse(await file.text());if(p.version!==1||!Array.isArray(p.completed)||p.completed.some(n=>!Number.isInteger(n)||n<1||n>24)||!p.notes||Array.isArray(p.notes)||typeof p.notes!=='object'||Object.entries(p.notes).some(([k,v])=>!/^([1-9]|1[0-9]|2[0-4])$/.test(k)||typeof v!=='string'))throw Error('Invalid course progress format');progress={version:1,completed:[...new Set(p.completed)],notes:p.notes};document.querySelectorAll('[data-note]').forEach(t=>t.value=progress.notes[t.dataset.note]||'');save();$('storage-status').textContent='Progress imported.'}catch(e){$('storage-status').textContent=e.message}$('progress-import').value=''};
$('menu-button').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('menu-button').setAttribute('aria-expanded',String(open))};$('show-foundations').onclick=()=>{$('foundation-frame').hidden=false;$('advanced-frame').hidden=true;$('show-foundations').classList.add('primary');$('show-advanced').classList.remove('primary')};$('show-advanced').onclick=()=>{$('foundation-frame').hidden=true;$('advanced-frame').hidden=false;$('show-advanced').classList.add('primary');$('show-foundations').classList.remove('primary')};window.addEventListener('hashchange',()=>show(location.hash.slice(1)));updateProgress();if(!storageOK)$('storage-status').textContent='Browser storage unavailable. Export progress before closing.';show(location.hash.slice(1)||'home');'''
js=js.replace('__SEARCH__',json.dumps(search).replace('</','<\\/')).replace('__ATLASES__',json.dumps({'foundation':(ROOT/'visuals/harness-experiments.html').read_text(),'advanced':(ROOT/'visuals/advanced-atlas.html').read_text()}).replace('</','<\\/'))
resources=''.join(f'<button data-page="{id}">{title}</button>' for id,title in [('home','Course home'),('guide','Start here'),('visuals','Visual models'),('labs','Lab guide'),('assessments','Assessments'),('reference','Quick reference'),('research','Research'),('curriculum','Curriculum')])
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Harness Engineering — Complete Course</title><style>{css}</style></head><body><header><button id="menu-button" aria-label="Toggle course navigation" aria-expanded="false">☰</button><div class="brand">HARNESS ENGINEERING <span>/ Complete course</span></div><div class="header-tools"><div class="progressbar" aria-hidden="true"><span id="progress-fill"></span></div><span class="progress-count" id="progress-count">0/24</span><button id="progress-export">Export progress</button><button id="progress-import-button">Import</button><input id="progress-import" type="file" accept="application/json,.json" hidden></div></header><noscript>This reader needs JavaScript for lesson navigation. All lesson text is also supplied in Markdown and PDF in the ZIP.</noscript><div class="layout"><aside aria-label="Course navigation"><label class="small" for="search">Search all lesson content</label><input type="search" id="search" placeholder="Try idempotency or reducer"><div class="resource-nav">{resources}</div><div class="nav-label">24 lessons · 12 modules</div>{''.join(nav)}<p id="search-empty" hidden>No matching lessons. Try a broader term.</p><div class="nav-label">Portable study record</div><button id="sidebar-export">Export progress and notes</button><p id="storage-status" role="status"></p></aside><main>{''.join(pages)}</main></div><script>{js}</script></body></html>'''
(ROOT/'Harness-Engineering-Reader.html').write_text(page)
print('Reader:',len(page),'characters,',len(lessons),'lessons')
